var n={en:`Customers order restaurant meals, authorize payment and await courier pickup. Restaurant rejection, payment failure and courier timeout are expected.`,ua:`Клієнти замовляють їжу, авторизують оплату й очікують кур’єра. Відмова ресторану, збій платежу й таймаут кур’єра — очікувані випадки.`};var s={en:[`Define service-owned data and API versus event edges.`,`Draw order states, payment and courier coordination.`,`Specify compensation, idempotency and delayed event handling.`],ua:[`Визнач власність даних сервісів і типи API/подієвих зв’язків.`,`Намалюй стани замовлення, оплату й координацію кур’єра.`,`Опиши компенсації, ідемпотентність і запізнілі події.`]};var t=[{en:`Mutable business data has one owning service.`,ua:`Змінювані бізнес-дані мають одного власника.`},{en:`No transaction assumes atomic writes across independent services.`,ua:`Жодна транзакція не припускає атомарний запис через незалежні сервіси.`}];var r={scenario:n,tasks:s,checks:t};export{t as checks,r as default,n as scenario,s as tasks};